def three(data):
    years=''.join(f'<button data-year="{y}">{y}</button>' for y in range(2016,2025))
    body='''<body><main class="page three-page"><header class="header"><div><h1>城市生长的<span>三维坐标</span></h1><p class="scope">道路、绿地与天然气服务 · 2016—2024</p></div><nav class="nav"><a href="11_城市运行大屏.html">城市运行图谱 ↗</a><a href="12_城市设施夜景大屏.html">设施观察台 ↗</a></nav></header><section class="three-layout"><article class="stage"><div class="chart-head"><h2>年度轨迹</h2><span class="unit">拖动旋转 · 滚轮缩放 · 点击选年</span></div><div class="stage-chart" id="threeStage" role="img" aria-label="人均道路、人均公园绿地与天然气服务人口的三维年度轨迹"></div></article><aside class="three-aside"><section class="three-values" id="threeValues" aria-label="所选年份原始指标"></section><section class="chart-block projection"><div class="chart-head"><h2>看清二维投影</h2></div><div class="chart" id="projectionChart" role="img" aria-label="人均道路与人均公园绿地的二维年度轨迹"></div></section><p class="three-note">每个点代表一年，连线表示时间先后。坐标轴按观测范围展开；共同变化不代表因果。</p></aside></section><section class="year-control three-controls"><strong id="yearLabel">2024</strong><div class="year-track"><input id="yearRange" type="range" min="2016" max="2024" value="2024" aria-label="年份"><div class="year-ticks">'''+years+'''</div></div><button class="camera" id="resetCamera">复位视角</button></section><footer class="footer"><span>国家统计局 · 浙江省城市汇总　<button id="openMethods">数据口径</button></span><span id="threeStatus">正在绘制</span></footer></main>'''+METHODS
    script=COMMON_SCRIPT.replace('PAYLOAD',json.dumps(data,ensure_ascii=False).replace('</','<\\/'))+THREE_SCRIPT
    return _wrap('浙江城市 · 三维探索',THREE_CSS,body,script)
